drop,keep,unm=[],{},[]
for n,q,c,com in rows:
    t=L(q); 
    tp=None
    if (com and 'удаляй' in com) or re.search(r'больше русских|сервак не \?|новый сервак не',t):
        drop.append((q,c,'Вы отметили: не к сайту',com));continue
    for name,rx in TOPICS[:2]:  # вайп и новые сервера до тех-фильтра (пользователь ответил на них)
        if re.search(rx,t) and not re.search(r"бля|хуй|пизд|ебан|заеб|помойк|гнид|далбаеб|успокойтесь|кто вам|какой вайп|правда\?|воздух|точная инфа|откуда инфа|зачем откры|почин|альт ф4|не всегда|мясн|откройте|сервак не|трабл|в пачку|онлайн|зачем делают|на новых серв|лучше работает|серверам все|ситуация|кто то говорит",t): tp=name;break
    if not tp:
        r=next((nm for nm,rx in DROP if re.search(rx,t)),None)
        if r: drop.append((q,c,r,com));continue
        tp=next((nm for nm,rx in TOPICS[2:] if re.search(rx,t)),None)
    if tp: keep.setdefault(tp,[]).append((q,c,com))
    else: unm.append((n,q))
json.dump(dict(drop=drop,keep=keep,unm=unm),open('/tmp/claude-0/w/res.json','w'),ensure_ascii=False)
print('удалено',len(drop),'в темах',sum(len(v) for v in keep.values()),'не распределено',len(unm))
for k,v in keep.items(): print(f'{len(v):4} {k}')
